use crate::aap::caps::http_client;
use crate::aap::caps::types::{FeedDocument, FetchFailure};

/// The hosts this node's `HTTPClient` handle is scoped to. The host enforces
/// this (an out-of-allowlist request traps); checking here as well lets one
/// mistyped subscription be reported as a failure instead of aborting the run.
const ALLOWED_HOSTS: [&str; 4] = [
    "simonwillison.net",
    "rss.arxiv.org",
    "bytecodealliance.org",
    "lobste.rs",
];

/// Extract the lowercase host of an http(s) URL, or None if it cannot be parsed.
fn host_of(url: &str) -> Option<String> {
    let trimmed = url.trim();
    let lower = trimmed.to_ascii_lowercase();
    let rest = if lower.starts_with("https://") {
        &trimmed[8..]
    } else if lower.starts_with("http://") {
        &trimmed[7..]
    } else {
        return None;
    };
    let end = rest
        .find(|c: char| c == '/' || c == '?' || c == '#')
        .unwrap_or(rest.len());
    let authority = &rest[..end];
    // Drop any userinfo.
    let host_port = match authority.rfind('@') {
        Some(i) => &authority[i + 1..],
        None => authority,
    };
    // Drop any port.
    let host = match host_port.rfind(':') {
        Some(i) => {
            let port = &host_port[i + 1..];
            if port.chars().all(|c| c.is_ascii_digit()) {
                &host_port[..i]
            } else {
                return None;
            }
        }
        None => host_port,
    };
    let host = host.trim_end_matches('.').to_ascii_lowercase();
    if host.is_empty() {
        None
    } else {
        Some(host)
    }
}

fn allowed(url: &str) -> Result<(), String> {
    match host_of(url) {
        None => Err(String::from("unparseable or non-http(s) URL")),
        Some(h) if ALLOWED_HOSTS.iter().any(|a| *a == h) => Ok(()),
        Some(h) => Err(format!("host '{}' is not in this node's allowlist", h)),
    }
}

struct Node;

impl Guest for Node {
    fn run(subscriptions: SubscriptionList) -> FeedBatch {
        let mut documents = Vec::new();
        let mut failures = Vec::new();

        for url in subscriptions.urls {
            if let Err(error) = allowed(&url) {
                failures.push(FetchFailure { url, error });
                continue;
            }
            match http_client::fetch(url.trim()) {
                Ok(body) => documents.push(FeedDocument { url, body }),
                Err(error) => failures.push(FetchFailure { url, error }),
            }
        }

        FeedBatch {
            documents,
            failures,
        }
    }
}

export!(Node);
```

